/* @autogenerated */
package net.civeira.phylax.common.infrastructure.exceptionmapper.sql;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.sql.SQLException;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import java.util.function.Supplier;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import jakarta.ws.rs.core.Response;
import net.civeira.phylax.common.infrastructure.sql.NotEmptyChildsException;
import net.civeira.phylax.common.infrastructure.sql.NotExistentReferenceException;
import net.civeira.phylax.common.infrastructure.sql.NotUniqueException;
import net.civeira.phylax.common.infrastructure.sql.OptimistLockException;
import net.civeira.phylax.common.infrastructure.sql.UncheckedSqlException;
import net.civeira.phylax.testing.mock.LoggerChecker;

@DisplayName("SQL exception mappers")
class SqlExceptionMappersUnitTest {
  private static final SQLException CAUSE = new SQLException("db");

  /**
   * Runs the mapping once with DEBUG, once with INFO and once with logging disabled, so every log
   * level guard is evaluated both ways. Returns the response of the last run.
   */
  private static Response atEveryLevel(Object mapper, Supplier<Response> mapping) {
    try (LoggerChecker checker = LoggerChecker.bind(mapper)) {
      List<Consumer<LoggerChecker>> levels = List.of(LoggerChecker::setLevelToDebug,
          LoggerChecker::setLevelToInfo, LoggerChecker::setLevelToOff);
      Response last = null;
      for (Consumer<LoggerChecker> level : levels) {
        level.accept(checker);
        last = mapping.get();
      }
      return last;
    }
  }

  @SuppressWarnings("unchecked")
  private static String reason(Response response) {
    return ((Map<String, String>) response.getEntity()).get("reason");
  }

  @Test
  @DisplayName("NotEmptyChildsExceptionMapper should answer 422")
  void notEmptyChildsShouldAnswer422() {
    NotEmptyChildsExceptionMapper mapper = new NotEmptyChildsExceptionMapper();
    Response response =
        atEveryLevel(mapper, () -> mapper.toResponse(new NotEmptyChildsException("childs", CAUSE)));
    assertEquals(422, response.getStatus());
    assertEquals("childs", reason(response));
  }

  @Test
  @DisplayName("NotExistentReferenceExceptionMapper should answer 422")
  void notExistentReferenceShouldAnswer422() {
    NotExistentReferenceExceptionMapper mapper = new NotExistentReferenceExceptionMapper();
    Response response = atEveryLevel(mapper,
        () -> mapper.toResponse(new NotExistentReferenceException("missing", CAUSE)));
    assertEquals(422, response.getStatus());
    assertEquals("missing", reason(response));
  }

  @Test
  @DisplayName("NotUniqueExceptionMapper should answer 422")
  void notUniqueShouldAnswer422() {
    NotUniqueExceptionMapper mapper = new NotUniqueExceptionMapper();
    Response response =
        atEveryLevel(mapper, () -> mapper.toResponse(new NotUniqueException("dup", CAUSE)));
    assertEquals(422, response.getStatus());
    assertEquals("dup", reason(response));
  }

  @Test
  @DisplayName("OptimistLockExceptionMapper should answer 412")
  void optimistLockShouldAnswer412() {
    OptimistLockExceptionMapper mapper = new OptimistLockExceptionMapper();
    Response response =
        atEveryLevel(mapper, () -> mapper.toResponse(new OptimistLockException("stale")));
    assertEquals(412, response.getStatus());
    assertEquals("stale", reason(response));
  }

  @Test
  @DisplayName("UncheckedSqlExceptionMapper should answer 500")
  void uncheckedSqlShouldAnswer500() {
    UncheckedSqlExceptionMapper mapper = new UncheckedSqlExceptionMapper();
    Response response =
        atEveryLevel(mapper, () -> mapper.toResponse(new UncheckedSqlException("boom", CAUSE)));
    assertEquals(500, response.getStatus());
    assertEquals("boom", reason(response));
  }
}
